import { sendRequest } from '../../core/utils/_utils.ajax';
import * as ko from 'knockout';
import { PrepareRequestArgs } from '../../core/internal/requestManager';
import { getParentContainer } from '../_utils';
import { DxDeferred } from '../../core/utils/_jqueryUtils';
import { Disposable } from '../../serializer/disposable';
import { getLocalization } from '../../property-grid/localization/_localization';
export class AIExpressionGenerator extends Disposable {
    constructor(model, uri, errorCallback) {
        super();
        this.model = model;
        this.buttons = ko.pureComputed(() => {
            const generateButton = {
                name: 'send',
                location: 'after',
                options: {
                    icon: 'send',
                    stylingMode: 'text',
                    type: 'default',
                    disabled: this.generationDisabled(),
                    onClick: this.generateAndApplyExpression,
                    visible: !this.isLoading(),
                    hint: 'Generate and Apply',
                    elementAttr: {
                        'aria-label': 'Generate and Apply'
                    }
                }
            };
            const stopButton = {
                name: 'stop',
                location: 'after',
                options: {
                    text: 'Stop',
                    stylingMode: 'text',
                    type: 'danger',
                    onClick: this.reset,
                    visible: this.isLoading()
                }
            };
            return [generateButton, stopButton];
        });
        this.applyDisabled = ko.observable(true);
        this._promptPlaceholder = getLocalization('Ask to generate an expression...', 'StringId.AIInputSuggestExpression');
        this.isLoading = ko.observable(false);
        this.expressionInNL = ko.observable('');
        this.generatedExpressionResult = ko.observable('');
        this.handleUri = uri;
        this.errorCallback = errorCallback;
        this.addDisposable(this.generationDisabled = ko.pureComputed(() => {
            return this.isLoading() || this.expressionInNL().length === 0;
        }));
    }
    reset() {
        this.dxGenerateExpressionDeferred?.resolve({ canceled: true });
        this.isLoading(false);
        this.generatedExpressionResult('');
    }
    initialize(editor) {
        this.reset();
        this.expressionInNL('');
        this.editor = editor;
        return this;
    }
    getLoadPanelOptions(element) {
        const loaderContainer = this.getLoadingPanelContainer(element);
        return {
            visible: this.isLoading,
            position: { of: loaderContainer },
            container: loaderContainer,
            wrapperAttr: { class: 'dxrd-ai-expression-loading-panel' }
        };
    }
    getLoadingPanelContainer(element) {
        return getParentContainer(element, '.dxrd-ai-expression-loading-panel-container');
    }
    generateAndApplyExpression() {
        this.generateExpression().then(() => {
            this.applyExpression();
        });
    }
    applyExpression() {
        if (!this.editor)
            return;
        const result = this.generatedExpressionResult();
        this.editor.setCriteriaValue(result);
        this.reset();
    }
    failRequestHandler(errorMessage) {
        this.errorCallback?.(errorMessage);
    }
    generateExpression() {
        if (this.generationDisabled() || !this.editor)
            return;
        this.reset();
        const deferred = new DxDeferred();
        this.dxGenerateExpressionDeferred = deferred;
        this.isLoading(true);
        this.applyDisabled(true);
        const reportLayoutJson = this.model()?.serialize?.();
        const context = this.editor.getEditorContext();
        const request = {
            prompt: this.expressionInNL(),
            reportLayoutJson: JSON.stringify({
                'XtraReportsLayoutSerializer': reportLayoutJson
            }),
            context: context
        };
        sendRequest(this.handleUri, 'generateExpression', PrepareRequestArgs(request))
            .then((result) => deferred.resolve(result), (fail) => deferred.reject(fail))
            .always(() => {
            this.isLoading(false);
        });
        return deferred
            .then((result) => {
            if (result.canceled)
                return;
            if (result.success) {
                this.generatedExpressionResult(result.text);
                this.applyDisabled(false);
            }
            else {
                this.failRequestHandler(result.errorMessage);
            }
        })
            .fail((fail) => this.failRequestHandler(fail));
    }
    dispose() {
        super.dispose();
        this.errorCallback = null;
        this.dxGenerateExpressionDeferred?.reject();
        this.dxGenerateExpressionDeferred = null;
    }
}
